export function subjectFor(icon) {const subject=aliases[icon]??(S[icon]?icon:null);if(!subject||!S[subject])throw Error(`Missing drawn subject: ${icon} -> ${subject}`);return subject;}
export function subjectSvg(subject,{color='#9d6d38',accent='#dfa94b',modifier='',angle=0}={}) {
 if(!S[subject])throw Error(`Unknown subject: ${subject}`);
 const mark=modifier==='x'?l('M4 4 21 21M21 4 4 21'):modifier==='off'?l('M2 2 23 23'):modifier==='check'?l('M3 12 10 20 23 4'):modifier==='plus'?l('M12 2V22M2 12H22'):modifier==='minus'?l('M2 12H22'):'';
 return `<g transform="rotate(${angle} 12 12)" stroke="#57402c" stroke-width=".7" stroke-linecap="round" stroke-linejoin="round" fill="url(#object-paint)">${S[subject]}<g opacity=".12" stroke="#473020" stroke-width=".2" fill="url(#engraving)">${S[subject]}</g>${mark?`<g fill="none" stroke="${accent}" stroke-width="1.5">${mark}</g>`:''}</g>`;
}
